  'help.guide.create-list.tip.1': 'ภาพปกจะอัปโหลดเองหรือหาจากการค้นหา Unsplash ในหน้าต่างเดียวกันก็ได้',
  // add-place
  'help.guide.add-place.title': 'เพิ่มสถานที่',
