  'help.guide.add-place.step.1':
    'กด + ที่ต้นแถวตัวกรองเหนือรายการสถานที่ ถ้ารายการยังว่างอยู่ ให้กด “เพิ่มสถานที่” ตรงกลางหน้า',
  'help.guide.add-place.step.2':
    'พิมพ์ชื่อสถานที่ในช่องค้นหาแล้วเลือกผลลัพธ์ ชื่อ ที่อยู่ และพิกัดจะถูกกรอกให้จากผลลัพธ์นั้น',
  'help.guide.add-place.step.3':
    'ตั้งสถานะ และถ้าต้องการ ใส่หมวดหมู่ คำอธิบาย และลิงก์ แล้วกด “เพิ่ม” กล่องโต้ตอบจะเปิดค้างไว้ให้เพิ่มสถานที่ถัดไป “ยกเลิก” ใช้ปิดกล่อง',
  'help.guide.add-place.result': 'สถานที่จะปรากฏในรายการ และเมื่อมีพิกัดจะแสดงเป็นหมุดบนแผนที่',
  'help.guide.add-place.tip.1':
    'เมื่ออยู่ในทริป “บันทึกลงคอลเลกชัน” ในตัวตรวจสอบสถานที่หรือในเมนูของสถานที่ จะเพิ่มสถานที่ของทริปลงรายการได้โดยไม่ต้องออกจากทริป',
  'help.guide.add-place.tip.2':
    'รายการต้องเป็นของคุณ หรือเป็นรายการที่คุณเป็นบรรณาธิการหรือผู้ดูแลระบบ ปุ่ม + จะไม่มีใน บันทึกทั้งหมดแล้ว หรือในรายการที่คุณดูได้อย่างเดียว',
  // import-from-trip
  'help.guide.import-from-trip.title': 'นำเข้าสถานที่จากทริป',
  'help.guide.import-from-trip.goal': 'ดึงสถานที่ทั้งหมดของทริปเข้ารายการในครั้งเดียว ไม่ต้องบันทึกทีละแห่ง',
  'help.guide.import-from-trip.step.1':
    'กดปุ่มนำเข้าที่เป็นรูปเมฆมีลูกศรในแถวตัวกรอง ถ้ารายการยังว่าง ปุ่มเดียวกันจะอยู่ข้าง “เพิ่มสถานที่”',
  'help.guide.import-from-trip.step.2': 'เลือกหนึ่งในทริปของคุณ',
  'help.guide.import-from-trip.step.3':
    'ติ๊กสถานที่ที่ต้องการ สถานที่ที่อยู่ในรายการแล้วจะเป็นสีเทา ตอนเปิดมา ระบบจะเลือกสถานที่ที่ยังไม่อยู่ในวันใดของทริปไว้ให้ก่อน แต่ถ้าทุกแห่งอยู่ในวันใดวันหนึ่งแล้ว จะเลือกสถานที่ใหม่ทั้งหมดแทน ตัวเลือก “ใหม่เท่านั้น” จะซ่อนสถานที่ที่รายการมีอยู่แล้ว',
  'help.guide.import-from-trip.step.4': 'กด “นำเข้า” ปุ่มจะบอกเสมอว่ากำลังจะเพิ่มกี่รายการ',
