  // place-detail
  'help.guide.place-detail.title': 'เปิดสถานที่ที่บันทึกไว้',
  'help.guide.place-detail.goal': 'ดูทุกอย่างเกี่ยวกับสถานที่และสิ่งที่ทำได้: แก้ไข คัดลอกไปยังทริป หาทางไป และลบออก',
  'help.guide.place-detail.step.1': 'คลิกแถวสถานที่ แผ่นรายละเอียดจะเปิดข้างรายการ และแผนที่จะเลื่อนไปยังสถานที่นั้น',
  'help.guide.place-detail.step.2':
    'ด้านล่างมีปุ่ม “แก้ไข”, “คัดลอกไปที่การเดินทาง”, ปุ่มนำทางที่เปิดสถานที่ในแอปแผนที่ และ “ลบออกจากรายการ” ไอคอนกล้องบนภาพปกใช้เปลี่ยนรูปที่ระบบหาให้เป็นรูปของคุณเอง',
  'help.guide.place-detail.result':
    'กด “แก้ไข” แล้วแก้ชื่อ หมวดหมู่ ป้ายกำกับ ที่อยู่ พิกัด คำอธิบาย และลิงก์ได้ในแผ่นรายละเอียดเลย',
  'help.guide.place-detail.tip.1':
    'ถ้าสถานที่ไม่มีรูปของตัวเอง ระบบจะดึงภาพปกมาให้อัตโนมัติ รูปที่คุณอัปโหลดเองเป็น JPG, PNG, GIF, WebP หรือ HEIC ได้ ขนาดไม่เกิน 20 MB ไอคอนถังขยะข้างไอคอนกล้องจะคืนรูปอัตโนมัติกลับมา',
  'help.guide.place-detail.tip.2':
    'สมาชิกทุกคนรวมถึงคุณให้ดาวคะแนนได้ใต้สถานะ ตัวกรอง “เรตติ้ง” ในแถวตัวกรองใช้ค่าเฉลี่ย',
  // labels
  'help.guide.labels.title': 'จัดกลุ่มสถานที่ด้วยป้ายกำกับ',
