  'help.guide.labels.tip.1':
    'ป้ายกำกับเป็นของรายการที่สร้างป้ายนั้นเท่านั้น การย้ายสถานที่ไปยังรายการอื่นจะทำให้ป้ายกำกับหายไป',
  'help.guide.labels.tip.2': 'การจัดการและกำหนดป้ายกำกับต้องมีสิทธิ์แก้ไขรายการ',
  // filter-select
  'help.guide.filter-select.title': 'กรองและเลือกสถานที่',
