  'help.guide.filter-select.result': 'การดำเนินการจะมีผลกับสิ่งที่เลือกทั้งหมดพร้อมกัน กด × ทางขวาเพื่อออกจากโหมดเลือก',
  'help.guide.filter-select.tip.1':
    '“เลือกทั้งหมด” จะเลือกเฉพาะสถานที่ที่ตรงกับตัวกรอง ถ้าจะจัดการสถานที่ “อยากไป” ทั้งหมด ให้กรองเป็น “อยากไป” แล้วกด “เลือกทั้งหมด”',
  // copy-to-trip
